<template><OperationsFrame title="操作审计">
 <el-form :inline="true" :model="query" v-show="showSearch"><el-form-item label="操作账号"><el-input v-model="query.account" clearable placeholder="账号ID" @keyup.enter="search" /></el-form-item><el-form-item label="操作"><el-input v-model="query.action" clearable placeholder="操作名称或接口" @keyup.enter="search" /></el-form-item><el-form-item label="来源"><el-select v-model="query.source" clearable placeholder="全部"><el-option v-for="(label,value) in sourceLabels" :key="value" :value="value" :label="label" /></el-select></el-form-item><el-form-item label="结果"><el-select v-model="query.outcome" clearable placeholder="全部"><el-option value="SUCCESS" label="成功" /><el-option value="FAILURE" label="失败" /></el-select></el-form-item><el-form-item label="井场ID"><el-input v-model="query.fieldId" clearable placeholder="井场ID" @keyup.enter="search" /></el-form-item><el-form-item label="操作时间"><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" /></el-form-item><el-form-item><el-button type="primary" icon="Search" @click="search">搜索</el-button><el-button icon="Refresh" @click="reset">重置</el-button></el-form-item></el-form>
 <div class="operations-toolbar"><el-button type="warning" plain icon="Download" :loading="exporting" @click="download">导出</el-button><right-toolbar v-model:showSearch="showSearch" @queryTable="load" /></div>
 <el-table :data="rows" v-loading="loading"><el-table-column label="来源" width="120"><template #default="{row}">{{sourceLabels[row.source]}}</template></el-table-column><el-table-column prop="actorName" label="操作账号ID" min-width="130" /><el-table-column prop="action" label="操作" min-width="260" show-overflow-tooltip /><el-table-column prop="fieldId" label="井场ID" width="90" /><el-table-column prop="wellId" label="井ID" width="85" /><el-table-column prop="surveyVersionId" label="测斜版本" width="100" /><el-table-column label="结果" width="80"><template #default="{row}"><el-tag :type="row.outcome==='SUCCESS'?'success':'danger'">{{row.outcome==='SUCCESS'?'成功':'失败'}}</el-tag></template></el-table-column><el-table-column prop="createTime" label="时间" width="180" /><el-table-column label="操作" width="80" fixed="right"><template #default="{row}"><el-button link type="primary" @click="detail=row">详情</el-button></template></el-table-column></el-table>
 <pagination v-show="total>0" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load" />
 <el-dialog :model-value="!!detail" title="审计详情" width="760px" class="operations-dialog" @close="detail=null"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item label="记录">{{detail.eventKey}}</el-descriptions-item><el-descriptions-item label="账号ID">{{detail.actorName||'—'}}</el-descriptions-item><el-descriptions-item label="资源">{{detail.resource}}</el-descriptions-item><el-descriptions-item label="任务">{{detail.taskId||'—'}}</el-descriptions-item><el-descriptions-item label="请求编号">{{detail.requestId||'—'}}</el-descriptions-item><el-descriptions-item label="IP / 耗时">{{detail.clientIp||'—'}} / {{detail.durationMs}} ms</el-descriptions-item></el-descriptions><pre>{{prettyJson(detail.detailJson)}}</pre></template></el-dialog>
</OperationsFrame></template>
<script setup>
import {ref} from 'vue';import OperationsFrame from './OperationsFrame.vue';import {useOperations,prettyJson,sourceLabels} from './useOperations';import {exportOperation} from '@/api/operations';
const {rows,total,loading,query,showSearch,dateRange,params,load,search,reset}=useOperations('audit',{account:'',action:'',fieldId:'',source:'',outcome:''});const detail=ref(null),exporting=ref(false)
async function download(){exporting.value=true;try{await exportOperation('audit',params())}catch{}finally{exporting.value=false}}
</script>
